import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Core Inference & Chat","description":"","frontmatter":{"epic":1,"title":"Core Inference & Chat","status":"✅ Complete — tasks 1.1 through 1.6","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/core-inference-chat.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/core-inference-chat.md","filePath":"sovereign-edge/epics/mobile/core-inference-chat.md"}'),i={name:"sovereign-edge/epics/mobile/core-inference-chat.md"};function r(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="epic-core-inference-chat" tabindex="-1">Epic: Core Inference &amp; Chat <a class="header-anchor" href="#epic-core-inference-chat" aria-label="Permalink to &quot;Epic: Core Inference &amp; Chat&quot;">​</a></h1><blockquote><p><code>llama.rn</code>/GGUF engine, model manager, and a fully offline chat and writing assistant — the part of the app with no network code path at all.</p></blockquote><p>The offline guarantee is now enforced rather than intended: see <a href="./../../network-audit.html">docs/network-audit.md</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The foundation the entire privacy claim rests on. Everything in this epic must work with the device in airplane mode. This is scenario 1 from the original brainstorm: open the app, brainstorm something, fix grammar, draft/rewrite an email — all fully local.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-1-1-—-llama-rn-integration-and-inference-engine-wrapper" tabindex="-1">✅ 1.1 — <code>llama.rn</code> integration and inference engine wrapper <a class="header-anchor" href="#✅-1-1-—-llama-rn-integration-and-inference-engine-wrapper" aria-label="Permalink to &quot;✅ 1.1 — `llama.rn` integration and inference engine wrapper&quot;">​</a></h4><p><strong>Goal:</strong> Get a GGUF model running on-device via <code>llama.rn</code>, wrapped in a clean internal API the chat UI and connector framework both call.</p><p><strong>Deliverables:</strong></p><ul><li><code>llama.rn</code> integrated for both iOS and Android.</li><li>An internal inference wrapper (load model, stream tokens, unload model) independent of any specific model file.</li><li>Basic perf validation on a real low/mid-range device, not just a simulator/emulator.</li></ul><p><strong>Dependencies:</strong> Task 0.1 (repo scaffold), Task 0.4 (model asset pipeline).</p><p><strong>Review checklist:</strong></p><ul><li><p>Chat streams tokens from a locally-downloaded GGUF model with the device&#39;s network interfaces disabled.</p></li><li><p>✅ Verified on an iPhone 15 Pro (A17 Pro, 7.50 GB), Release build. Metal is active — <code>GPU=true</code>, where every earlier figure came from an emulator reporting <code>gpu=false</code> and running CPU-only. Generation reached 86–91 tok/s against ~43 on the emulator, with time-to-first-token 233 ms cold and 17 ms warm against 1123 ms.</p></li></ul><p><strong>Two findings worth carrying forward.</strong> Model load took <strong>8.7 s</strong> on device against 1.8 s on the emulator — GPU acceleration is <em>why</em>, since Metal must upload weights to GPU memory where the CPU-only path simply memory-mapped them. So the ~2x generation win costs roughly seven seconds up front, which task 1.3&#39;s chat UI has to show honestly rather than hide behind a spinner. Verification also revealed a redundant digest pass; see <a href="./../../research/0003-model-verification-hashing.html">research 0003</a>.</p><h2 id="not-established-both-available-test-devices-have-8-gb-so-every-modelrates-comfortable-and-the-memory-heuristic-remains-unexercised-near-itsboundary" tabindex="-1"><strong>Not established:</strong> both available test devices have 8 GB, so every model rates <code>comfortable</code> and the memory heuristic remains unexercised near its boundary. <a class="header-anchor" href="#not-established-both-available-test-devices-have-8-gb-so-every-modelrates-comfortable-and-the-memory-heuristic-remains-unexercised-near-itsboundary" aria-label="Permalink to &quot;**Not established:** both available test devices have 8 GB, so every model\nrates `comfortable` and the memory heuristic remains unexercised near its\nboundary.&quot;">​</a></h2><h4 id="✅-1-2-—-model-manager" tabindex="-1">✅ 1.2 — Model manager <a class="header-anchor" href="#✅-1-2-—-model-manager" aria-label="Permalink to &quot;✅ 1.2 — Model manager&quot;">​</a></h4><p><strong>Goal:</strong> Let a user pick, download, and manage which small model is installed.</p><p><strong>Deliverables:</strong></p><ul><li>Curated model catalog (small GGUF models — Gemma/Qwen/Phi-class; final list is an open question, see research 0001).</li><li>RAM-aware guidance/warnings per model, given the phone&#39;s available memory.</li><li>Delete/switch-model flow.</li></ul><p><strong>Dependencies:</strong> Task 1.1, Task 0.4.</p><p><strong>Review checklist:</strong></p><ul><li><p>✅ A user can download one model, chat, delete it, and download a different one without restarting the app. Verified end to end on an Android emulator: Qwen2.5 0.5B downloaded and verified (57s), loaded in 1.3s, replied &quot;Hello! How may I assist you?&quot;, was deleted; then Llama 3.2 1B downloaded, loaded in 2.8s, replied, and was deleted — all in one app session.</p><p><strong>This was verified against the pipeline, not the shipped UI, and for a while the distinction mattered.</strong> The Models screen arrived later (tasks 8.1 and 1.3) with no download control at all: <code>onPress</code> returned <code>undefined</code> for anything not already installed. A fresh install was therefore a dead end — chat said &quot;open Models to add one&quot; and Models offered nothing to press. Nothing caught it, because the checklist above had been signed off on a path no user could take, and both test devices already had model files left behind by the task 1.1 perf harness. It was found by running a fresh install on an emulator. The download UI now exists and the claim above is true of the shipped app: Qwen2.5 0.5B (491,400,032 bytes) downloaded, verified, auto-loaded, and answered a question, entirely from the UI.</p></li><li><p>✅ Confirmed on an iPhone 15 Pro as well, against a Release build reporting 0.1.10 to the OS — which is only usable as evidence because the native version was regenerated first; before that it read 0.1.4 and could not distinguish one install from another. Note this device cannot reproduce the first-run case: it still holds model files from the task 1.1 perf harness, so the Android emulator remains the evidence for the fresh-install path.</p></li><li><p>✅ The Llama entry carries no MD5, so it was verified purely against the publisher&#39;s SHA-256: 807 MB in 1.0s (~790 MB/s) via the native module from task <a href="./infrastructure.html#-05--native-sha-256-hashing">0.5</a>. The same check would have taken roughly ten minutes of JavaScript hashing before it.</p></li><li><p>✅ The RAM guidance is finally exercised near its boundary. Both physical devices have 8 GB, where every catalog entry rates <code>comfortable</code>; a 3.8 GB emulator renders all three tiers, including &quot;Likely too large for this device&quot; for Gemma 2 2B.</p></li></ul><p><strong>Found after this task closed, fixed in <a href="#-16--remember-the-chosen-model">1.6</a>.</strong> The checklist above was still true — switching worked, and nothing here claimed the choice would survive a relaunch.</p><ul><li><p><strong>The chosen model was not remembered across launches.</strong> The provider bootstrapped with <code>manager.list().find((m) =&gt; m.installed)</code> — the first <em>catalog</em> entry that happened to be installed, not the one the user picked. Switching deliberately to Llama 3.2 1B and relaunching put the app silently back on Qwen2.5 0.5B.</p><p>That was more than an annoyance: task 1.4 measured Draft fabricating a price on 0.5B and not on 1B, so it quietly returned the user to the model they had moved away from, with the mode warning as the only thing catching it. Found by accident — a Fast Refresh remount re-ran the bootstrap mid-session, made Qwen active again with no visible change, and the next tap on that row deleted a 491 MB download instead of selecting it. The destructive tap was a development artefact; the missing persistence was not.</p></li></ul><hr><h4 id="✅-1-3-—-offline-chat-ui" tabindex="-1">✅ 1.3 — Offline chat UI <a class="header-anchor" href="#✅-1-3-—-offline-chat-ui" aria-label="Permalink to &quot;✅ 1.3 — Offline chat UI&quot;">​</a></h4><p><strong>Goal:</strong> The core conversational interface.</p><p><strong>Deliverables:</strong></p><ul><li>Conversation view with streaming token rendering.</li><li>Local-only chat history (no export/sync in this task — that&#39;s a future, explicit opt-in decision per research 0001-equivalent follow-up).</li><li>Persistent visible indicator that the current conversation is fully offline (per CONCEPT.md&#39;s &quot;always show which trust tier is active&quot;).</li></ul><p><strong>Dependencies:</strong> Task 1.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Chat is fully usable with the device offline. Verified on an iPhone 15 Pro in airplane mode against a <strong>Release</strong> build — the distinction matters: a debug build fetches its JS from Metro over the LAN, so it cannot answer this question at all, and an early attempt against one had to be discarded. The Release binary embeds <code>main.jsbundle</code> (2.0 MB) and has no Metro path.</li><li>✅ The build was confirmed to be current code by reading the version off the Settings screen (0.1.10). That value is a JS constant compiled into the bundle, which is what makes it usable as evidence: the iOS <code>Info.plist</code> version is stale at 0.1.4, because <code>ios/</code> is CNG-generated and <code>expo run:ios</code> does not re-run prebuild, so the native version string cannot distinguish an old install from a new one.</li><li>✅ Verified on Android too, on an emulator, after the iOS run had already been signed off. Chat rendered, the model answered, and the composer behaved — but this is also where the fresh-install dead end recorded under task 1.2 turned up, because the emulator was the first device in the project without a model already sitting in its container. Single-platform verification would have missed it.</li></ul><p><strong>Delivered:</strong></p><ul><li><code>ChatScreen</code> renders streaming tokens into the reply as they arrive, keeps history in memory only, and offers Stop while a reply is generating — the engine supports aborting, and without it a user waits out a reply they no longer want.</li><li>A persistent banner names the trust tier and the loaded model, and carries the load-time explanation that finding above calls for: the 8.7 s wait is stated in words rather than hidden behind a spinner.</li><li><code>ChatSessionContext</code> (in <code>src/chat/session/</code>) is a narrow contract — status, model name, detail, <code>generate</code> — implemented by <code>ModelSessionProvider</code> in the app shell. This is what keeps <code>src/chat/</code> from importing <code>ModelManager</code> and, through it, the downloader, which research 0001 forbids.</li><li>One engine app-wide, in that same provider. A second concurrent context is the fastest route to an out-of-memory kill on a phone, and sharing one is also what lets the manager release a model before deleting it.</li></ul><hr><h4 id="✅-1-4-—-writing-assist-modes" tabindex="-1">✅ 1.4 — Writing-assist modes <a class="header-anchor" href="#✅-1-4-—-writing-assist-modes" aria-label="Permalink to &quot;✅ 1.4 — Writing-assist modes&quot;">​</a></h4><p><strong>Goal:</strong> The concrete scenario-1 use case — brainstorm, grammar-fix, rewrite/draft an email.</p><p><strong>Deliverables:</strong></p><ul><li>A small set of prompt-engineered modes/personas (brainstorm, fix grammar, rewrite tone, draft from bullet points) surfaced as quick actions in chat.</li><li>No connector involved — these are pure local-model tasks.</li></ul><p><strong>Dependencies:</strong> Task 1.3.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Each mode produces a materially different, appropriate transformation of the same input text. Measured on an Android emulator against both Qwen2.5 0.5B and Llama 3.2 1B: <ul><li>✅ <strong>Fix grammar</strong> — &quot;we needs to tell customers there prices is going up&quot; became &quot;We need to tell customers that prices are going up.&quot; Four corrections, no commentary, nothing else touched. Two runs at temperature 0.2 produced identical output.</li><li>⚠️ <strong>Brainstorm</strong> — returns a list rather than prose, but restates one idea five ways (&quot;pricing increase&quot;, &quot;rising prices&quot;, &quot;increasing prices&quot;), which its own prompt forbids. Temperature 0.95 does not rescue it.</li><li>❌ <strong>Draft</strong> — &quot;Prices rise 5 percent from March, loyal customers get 3 months notice&quot; produced a nine-line essay opening &quot;which implies that the prices have increased by <strong>$100 per customer</strong>&quot;. The figure is invented; the prompt says to invent no new facts, and to match length to input. A fabricated price in a draft the user may then send is the most damaging failure available to this feature, and it reads fluently enough to pass a skim.</li><li>✅ <strong>Rewrite tone</strong> (Llama 3.2 1B) — &quot;make this polite: prices are going up deal with it&quot; became &quot;I wanted to touch base with you regarding the pricing for our services…&quot;. Wraps its output in quotation marks, against &quot;return only the rewritten text&quot;.</li></ul></li></ul><p><strong>Re-measured on Llama 3.2 1B, same input, same prompt, only the model changed.</strong> Draft returned &quot;To accommodate our loyal customers, we will offer them 3 months&#39; notice before increasing prices…&quot; — no invented figure, and a short paragraph rather than an essay. It drops the 5 percent, so it omits a given fact instead of inventing one; a lesser fault, but still against the prompt.</p><p>So the prompts were not the problem and were deliberately left alone. Tuning them against the smallest catalog entry would have contorted them around a limitation that disappears one size up.</p><ul><li>✅ Draft warns when the loaded model is below 1B, naming the model and the specific failure rather than offering a generic disclaimer about AI. Scoped to the one mode and the sizes where fabrication was observed: it is absent on Fix grammar, which returns the user&#39;s own words corrected, and absent at 1B. Both directions verified on device. A warning shown everywhere becomes wallpaper, and the place it matters would be lost in it.</li></ul><p><strong>Known rough edges, recorded rather than fixed.</strong> Brainstorm on 0.5B restates one idea in several wordings, against its own prompt; repetitive options waste time but cannot mislead the way an invented figure can. Rewrite tone wraps its output in quotation marks, against &quot;return only the rewritten text&quot;. Draft on 1B drops a given fact (the 5 percent) — omission rather than invention.</p><ul><li>✅ A mode receives its system prompt and the current message only. Sending conversation history defeated modes outright: with two grammar corrections in the transcript, Brainstorm returned a third grammar correction, because a 0.5B model follows demonstrated behaviour over a system instruction. The same input in a fresh conversation returned ideas. Fixed and re-verified by reproducing the original two-turn sequence.</li></ul><hr><h4 id="✅-1-5-—-zero-network-enforcement-and-audit" tabindex="-1">✅ 1.5 — Zero-network enforcement and audit <a class="header-anchor" href="#✅-1-5-—-zero-network-enforcement-and-audit" aria-label="Permalink to &quot;✅ 1.5 — Zero-network enforcement and audit&quot;">​</a></h4><p><strong>Goal:</strong> Make the &quot;fully offline&quot; claim structurally true, not just true by current code review.</p><p>Every other task in this epic delivers a feature. This one delivers <em>evidence</em>. <a href="./../../research/0001-concept-and-connector-architecture.html#decisions">Research 0001</a> states that &quot;the chat/model/memory layers are 100% offline by design — no network code path exists there at all&quot;, and CONCEPT.md sells that to users. Today it is true because the people who wrote the code intended it. This task is what makes it survive a contributor who did not read this document.</p><h5 id="what-the-claim-actually-means" tabindex="-1">What the claim actually means <a class="header-anchor" href="#what-the-claim-actually-means" aria-label="Permalink to &quot;What the claim actually means&quot;">​</a></h5><p>Precision first, because &quot;offline app&quot; is not what is being claimed and promising it would be a lie — the app downloads model weights over HTTPS.</p><table tabindex="0"><thead><tr><th>Module</th><th>Network</th><th>Why</th></tr></thead><tbody><tr><td><code>src/chat/</code></td><td><strong>Never</strong></td><td>The claim. Conversations, prompts, and replies never leave the device.</td></tr><tr><td><code>src/models/</code></td><td><strong>User-initiated only</strong></td><td><em>Acquiring</em> a model is a visible, deliberate download. <em>Using</em> one never touches the network. The deliberate exception in AGENTS.md rule 3, and why it is a sibling of <code>chat/</code> rather than living inside it.</td></tr><tr><td><code>src/connectors/</code></td><td><strong>Per-grant only</strong></td><td>Every outbound call, behind an explicit, separately revocable, per-connector permission. Currently an empty directory — the framework is epic 2.</td></tr><tr><td><code>src/design-system/</code>, <code>src/shared/</code></td><td><strong>Never</strong></td><td>Not part of the claim as stated, but <code>chat/</code> imports them, so they are inside the boundary by transitivity.</td></tr></tbody></table><p>The enforceable statement is therefore narrower and sharper than &quot;the app is offline&quot;: <strong>no code path reachable from <code>src/chat/</code> can open a socket.</strong></p><h5 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h5><p>What actually breaks this, roughly in order of likelihood. An enforcement mechanism that does not address each of these is theatre.</p><ol><li><strong>A direct import.</strong> Someone adds <code>import { fetch } from &#39;expo/fetch&#39;</code> or an HTTP client to a file under <code>src/chat/</code>. The easy case, and the only one a naive lint rule catches.</li><li><strong>A global with no import at all.</strong> <code>fetch</code>, <code>XMLHttpRequest</code>, <code>WebSocket</code>, and <code>EventSource</code> are ambient in React Native. A file can reach the network without importing anything, so import-based rules alone are insufficient. This is the most likely way the boundary silently breaks.</li><li><strong>A transitive import.</strong> <code>src/chat/</code> imports something innocuous which, two or three hops down, reaches <code>src/models/download.ts</code> or a networked library. Lint sees one file at a time and cannot see this at all. Closing it needs a graph walk from <code>src/chat/**</code> across the resolved import tree. The <code>ChatSessionContext</code> inversion built in task 1.3 exists precisely to keep this edge from forming; the check is what proves it stays absent.</li><li><strong>A native module.</strong> JavaScript-level analysis cannot see a socket opened in Swift or Kotlin. <code>llama.rn</code> ships prebuilt native artifacts. Measured during scoping and found clean — see <em>Resolved before implementation</em> — but the hole stays open for any native module added later.</li><li><strong>A dependency update.</strong> A transitive npm package starts phoning home in a patch release. Not addressed by any check scoped to first-party source.</li></ol><h5 id="enforcement-layers-to-build" tabindex="-1">Enforcement layers to build <a class="header-anchor" href="#enforcement-layers-to-build" aria-label="Permalink to &quot;Enforcement layers to build&quot;">​</a></h5><p>Each is listed with what it <em>cannot</em> catch, because a mechanism whose limits are unstated will be trusted past them.</p><ul><li><strong>Lint: restricted imports</strong> under <code>src/chat/**</code>, denying network-capable modules by path and pattern. Follows the existing <code>no-restricted-syntax</code> colour rule in <code>eslint.config.js</code> — the precedent for turning a review checklist item into a check. <em>Cannot catch:</em> threats 2–5.</li><li><strong>Lint: restricted globals</strong> under <code>src/chat/**</code> for <code>fetch</code>, <code>XMLHttpRequest</code>, <code>WebSocket</code>, <code>EventSource</code>, and <code>navigator.sendBeacon</code>. Closes threat 2, which is the one most likely to occur. <em>Cannot catch:</em> 3–5.</li><li><strong>A module-graph check</strong>, run in CI, that resolves imports from every file under <code>src/chat/**</code> and fails if the closure reaches a denylisted module or any file outside the permitted set. This is the layer with real teeth and the only answer to threat 3. It needs to run on the same resolution Metro uses, or it will disagree with the shipped bundle.</li><li><strong>A runtime tripwire in development builds</strong> that replaces the network globals with throwing stubs while a chat screen is mounted. <code>jest.setup.js</code> already does this for tests and points at this task by name; the value here is catching a path that only executes at runtime.</li><li><strong>A written audit document</strong> covering the above plus the native surface: the declared platform permissions, why <code>INTERNET</code> cannot be dropped, and what a third party should run to reproduce every claim.</li></ul><h5 id="what-this-task-cannot-close" tabindex="-1">What this task cannot close <a class="header-anchor" href="#what-this-task-cannot-close" aria-label="Permalink to &quot;What this task cannot close&quot;">​</a></h5><p>Stating these plainly is part of the deliverable. An audit that overclaims is worse than none, because it transfers unearned trust.</p><ul><li><strong>Native code.</strong> No JavaScript check sees a socket opened inside <code>llama.rn</code>. Mitigation is auditing what that library links against and recording the finding — not asserting a guarantee the mechanism does not provide.</li><li><strong>Platform permissions cannot express this.</strong> <code>android.permission.INTERNET</code> is app-wide and genuinely required for model downloads, so it cannot be dropped to enforce the boundary. iOS has no per-module network entitlement either. This is why the enforcement is a module boundary rather than a platform control, and the audit should say so rather than leave a reader assuming the OS is enforcing something it is not.</li><li><strong>Third-party runtime behaviour</strong>, per threat 5.</li></ul><h5 id="findings-already-in-hand" tabindex="-1">Findings already in hand <a class="header-anchor" href="#findings-already-in-hand" aria-label="Permalink to &quot;Findings already in hand&quot;">​</a></h5><p>Turned up while scoping this task, and part of its audit surface:</p><ul><li><strong><code>AndroidManifest.xml</code> declares <code>SYSTEM_ALERT_WINDOW</code></strong> (draw over other apps), plus <code>VIBRATE</code> and legacy <code>READ</code>/<code>WRITE_EXTERNAL_STORAGE</code>. None are used by any first-party code; they are pulled in by dependencies and merged by the manifest merger. For an app whose pitch is restraint, shipping a draw-over-other-apps permission is a genuine audit smell — it is the kind of thing a reviewer finds and a user cannot explain away. The audit should enumerate every declared permission with a justification or a removal.</li><li><strong>iOS ATS is <code>NSAllowsArbitraryLoads: false</code></strong> (good) with <code>NSAllowsLocalNetworking: true</code>. The latter is what a Metro dev server needs; whether it should survive into Release builds is an open question below.</li></ul><p><strong>Dependencies:</strong> Task 1.1.</p><p><strong>Deliverables:</strong></p><ul><li>Lint rules covering threats 1 and 2, scoped to <code>src/chat/**</code>.</li><li>A CI module-graph check covering threat 3.</li><li>A development-time runtime tripwire.</li><li><code>docs/network-audit.md</code>: the enforced boundary, each mechanism and its limits, every declared platform permission with a justification, and the exact commands a third party runs to reproduce the claims.</li><li>Permission cleanup, or a recorded reason each one stays.</li></ul><p><strong>Review checklist:</strong></p><ul><li>✅ Attempting to add a network call inside the chat/inference module fails CI or the build, not just code review. Four mechanisms: restricted imports and restricted globals in <code>eslint.config.js</code>, a module-graph walk in <code>scripts/ci/check-offline-boundary.js</code> wired into CI as <code>pnpm check:offline</code>, and a development-only runtime tripwire armed from <code>App.tsx</code>.</li><li>✅ <strong>Each mechanism was verified by deliberately breaking it.</strong> Nine probes across the threat classes, each confirmed to fail for its stated reason and then reverted. The decisive one: an escape routed <code>chat/ → shared/helper → @/models</code> produced <strong>zero ESLint errors</strong> and was caught by the graph check, which printed the full three-step chain. That is the case lint provably cannot see, and the reason the graph check exists rather than being a belt-and-braces extra.</li><li>✅ A third party can reproduce every claim in <a href="./../../network-audit.html">docs/network-audit.md</a> from the commands it lists.</li><li>✅ Every Android permission is justified or removed. <strong>A Release build declares exactly one: <code>INTERNET</code>.</strong> <code>VIBRATE</code> and both legacy external storage permissions are removed via <code>android.blockedPermissions</code>; <code>SYSTEM_ALERT_WINDOW</code> turned out to be debug-only, added by React Native&#39;s dev overlay, and is absent from Release.</li></ul><p><strong>Two things the verification changed.</strong> The permission check had to move from the source manifest to the merged one — the source still lists blocked permissions carrying <code>tools:node=&quot;remove&quot;</code>, so grepping it reports the opposite of the truth, and the audit&#39;s original command would have misled a reader. And the runtime tripwire was tested against a real model download to confirm it does not break the one legitimate network path: <code>expo-file-system</code> downloads through native code rather than JS <code>fetch</code>, so a 1.12 GB transfer ran normally with the guard armed. That was an assumption until it was measured.</p><h5 id="resolved-before-implementation" tabindex="-1">Resolved before implementation <a class="header-anchor" href="#resolved-before-implementation" aria-label="Permalink to &quot;Resolved before implementation&quot;">​</a></h5><ul><li><p><strong>The graph check runs on source imports, not the bundle.</strong> Walking first-party imports from <code>src/chat/**</code> runs on every PR, points at the file and line that broke the rule, and covers the realistic failure. Bundle analysis is the stronger claim — it is what actually ships — but it is slow, its errors name generated module ids rather than source, and it cannot run until a bundle is built. Recorded as a follow-up rather than dropped: the gap it leaves is a dependency that reaches the network without any first-party file importing it, which is threat 5 and is not closed here.</p></li><li><p><strong>The runtime tripwire is development and test only.</strong> The static checks are the production guarantee; a violation reaching a Release build means CI already failed, and turning that into a user-visible crash punishes the user for the project&#39;s mistake. Failing closed in Release was the tempting choice for a product sold on this claim, and it was rejected because the crash would land on a path never exercised in testing — precisely the path least likely to have been the one anyone reasoned about.</p></li><li><p><strong><code>NSAllowsLocalNetworking</code> stays, and the reason is not Metro.</strong> Research 0001 specifies the Sovereign Tasks connector calling &quot;the user&#39;s self-hosted <code>sovereign</code> instance&quot;, and self-hosted instances commonly sit on a LAN. Stripping it would break a planned connector on exactly the deployment this product is built for. The audit records it as a connector requirement rather than a development leftover — the distinction matters, because a reader who sees it described as a dev artefact will reasonably ask why it shipped.</p></li><li><p><strong>The dependency audit covers only what <code>chat/</code> actually reaches</strong> — today <code>llama.rn</code>, <code>react</code>, <code>react-native</code>, and <code>react-native-safe-area-context</code>. That is the exact set the claim depends on, small enough to re-audit when it changes, and it does not rot into a list nobody rechecks. Everything else in <code>package.json</code> is out of scope and says so in the audit.</p></li><li><p><strong><code>llama.rn</code> links nothing network-capable.</strong> Measured rather than assumed, since this overlaps the unresolved prebuilt-binary supply-chain question in <a href="./../../research/0002-react-native-framework-choice.html">research 0002</a>. Both shipped artifacts — <code>ios/rnllama.xcframework</code> (arm64, 10,471,352 bytes) and <code>android/.../arm64-v8a/librnllama.so</code> (9,530,928 bytes) — have <strong>zero undefined network symbols</strong>: no <code>socket</code>, <code>connect</code>, <code>getaddrinfo</code>, <code>NSURLSession</code>, or <code>curl_*</code>. A library that opens a socket must import those from the system. The iOS/Android sources contain no <code>NSURLSession</code>, <code>HttpURLConnection</code>, <code>OkHttp</code>, or <code>java.net.*</code>, and the bundled C++ has no <code>sys/socket.h</code> or <code>curl</code> includes — upstream llama.cpp&#39;s optional <code>LLAMA_CURL</code> model downloader is not compiled in.</p><p>The binaries do contain URL-shaped strings — GitHub PR links from source comments, and <code>https://huggingface.co/</code> from llama.cpp&#39;s model-spec parsing — which are inert without socket symbols to act on them.</p><p><strong>Limits of this evidence</strong>, which the audit must carry rather than round off to &quot;verified safe&quot;: it covers arm64 artifacts via <code>nm</code> and <code>strings</code>, and a <code>dlsym</code>-based lookup would evade it. That would be extraordinary for an inference library, but &quot;we checked the imports table&quot; is the claim being made, not &quot;we proved it cannot&quot;.</p></li></ul><h5 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h5><ul><li><strong>Bundle-level analysis</strong>, per the first decision above. Closes threat 5; needs its own task.</li><li><strong>Threat 5 generally</strong> — a transitive npm package that starts phoning home in a patch release is not addressed by anything scoped to first-party source.</li></ul><h4 id="✅-1-6-—-remember-the-chosen-model" tabindex="-1">✅ 1.6 — Remember the chosen model <a class="header-anchor" href="#✅-1-6-—-remember-the-chosen-model" aria-label="Permalink to &quot;✅ 1.6 — Remember the chosen model&quot;">​</a></h4><p><strong>Goal:</strong> The model a user selects stays selected across app launches.</p><p><strong>Deliverables:</strong></p><ul><li>Persist the active model id alongside the model files.</li><li>Read it back at startup, falling back to the current &quot;first installed catalog entry&quot; behaviour when the stored id is no longer installed.</li></ul><p><strong>Dependencies:</strong> Task 1.2.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Switch to a model that is not first in the catalog, force-quit, relaunch, and it is still the one loaded. Verified on an Android emulator: selected Llama 3.2 1B (second in the catalog, with Qwen2.5 0.5B also installed), confirmed <code>active-model.json</code> held its id, force-stopped the app, and the banner came back reading &quot;On-device · Llama 3.2 1B Instruct&quot;. The first attempt at this check was worthless and had to be redone — Qwen was active, which is also what the old behaviour produces, so it distinguished nothing.</li></ul><p><strong>How it works.</strong> The id is stored beside the model files rather than in a settings store, so deleting a model reclaims both together and no preference is left pointing at nothing. <code>readActiveModelId</code> returns null once the file it names is gone, meaning a model removed by an OS clean-up or absent after a restore degrades to first-launch behaviour instead of failing to start. <code>remove()</code> clears the stored id whenever it names the model being deleted, including in a session that never loaded it — the stored choice outlives the session that set it, so <code>activeId</code> alone is not enough to know.</p><p><strong>Why this is not cosmetic.</strong> Task 1.4 measured Draft fabricating a price on Qwen2.5 0.5B and not on Llama 3.2 1B. Without persistence, a user who moved to the larger model for exactly that reason is returned to the smaller one on next launch, with no announcement. The mode&#39;s fabrication warning is currently the only thing standing between that and a draft they send.</p><hr><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li></ul>',89)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
